`70-89`: **Honor URL matching in createMockFetch or drop the unused option.**

responses[].url is ignored. Either support URL-based selection or remove it to avoid confusion. Example to support matching:


```diff
 export const createMockFetch = (
   responses: Array<{ url?: string; response: any; status?: number }>,
 ) => {
   let callIndex = 0;

-  return jest.fn((url: string) => {
-    const mockResponse =
-      responses[callIndex] || responses[responses.length - 1];
-    callIndex++;
+  return jest.fn((url: string) => {
+    const byUrl = responses.find((r) => !r.url || r.url === url);
+    const byIndex = responses[callIndex];
+    const mockResponse = byUrl ?? byIndex ?? responses[responses.length - 1];
+    if (callIndex < responses.length - 1) callIndex++;

     return Promise.resolve({
       ok:
         (mockResponse.status || 200) >= 200 &&
         (mockResponse.status || 200) < 300,
       status: mockResponse.status || 200,
       json: () => Promise.resolve(mockResponse.response),
       text: () => Promise.resolve(JSON.stringify(mockResponse.response)),
     });
   });
 };
```

